shellCommands.command:
/bin/bash -lc "cat <<'EOF' > app/globals.css
:root {
  color-scheme: light;
  --bg-warm: #f7f2e9;
  --bg-mint: #eaf3ef;
  --bg-amber: #fff4dd;
  --surface: #ffffff;
  --surface-muted: rgba(255, 255, 255, 0.78);
  --text: #1f2328;
  --muted: #5f6670;
  --accent: #0f766e;
  --accent-strong: #0b5f58;
  --accent-warm: #f59e0b;
  --border: rgba(15, 23, 42, 0.12);
  --shadow: 0 20px 45px rgba(15, 23, 42, 0.12);
  --shadow-soft: 0 12px 30px rgba(15, 23, 42, 0.08);
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--text);
  background:
    radial-gradient(circle at 12% 20%, rgba(245, 158, 11, 0.12), transparent 40%),
    radial-gradient(circle at 78% 12%, rgba(15, 118, 110, 0.15), transparent 45%),
    linear-gradient(120deg, var(--bg-warm), var(--bg-mint));
}

h1,
h2,
h3,
h4,
h5 {
  font-family: var(--font-display);
}

button {
  font-family: inherit;
}

::selection {
  background: rgba(15, 118, 110, 0.18);
}
EOF"

/bin/bash -lc "cat <<'EOF' > app/page.module.css
.page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 72px 24px 96px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}

.header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
  flex-wrap: wrap;
}

.titleBlock {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-width: 560px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.7rem;
  color: var(--muted);
}

.title {
  margin: 0;
  font-size: clamp(2.2rem, 4vw, 3.1rem);
  line-height: 1.05;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
}

.syncForm {
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 16px 18px;
  box-shadow: var(--shadow-soft);
  min-width: 220px;
}

.syncButton {
  border: none;
  border-radius: 999px;
  padding: 10px 18px;
  font-weight: 600;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: transform 150ms ease, box-shadow 150ms ease, background 150ms ease;
}

.syncButton:hover {
  background: var(--accent-strong);
  transform: translateY(-1px);
  box-shadow: 0 10px 18px rgba(15, 118, 110, 0.2);
}

.syncHint {
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 16px;
  box-shadow: var(--shadow-soft);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.cardLabel {
  margin: 0;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.cardValue {
  margin: 0;
  font-size: 1.6rem;
  font-weight: 600;
}

.cardNote {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.tableWrap {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 20px;
  box-shadow: var(--shadow);
  overflow: hidden;
}

.tableHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: linear-gradient(90deg, rgba(15, 118, 110, 0.12), rgba(245, 158, 11, 0.12));
  border-bottom: 1px solid var(--border);
  gap: 12px;
  flex-wrap: wrap;
}

.tableTitle {
  margin: 0;
  font-size: 1.2rem;
}

.tableMeta {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.tableScroll {
  overflow-x: auto;
}

.table {
  width: 100%;
  border-collapse: collapse;
  min-width: 640px;
}

.th,
.td {
  padding: 12px 20px;
  text-align: left;
  font-size: 0.95rem;
}

.th {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--muted);
  background: rgba(248, 250, 252, 0.8);
  border-bottom: 1px solid var(--border);
}

.tr {
  border-bottom: 1px solid rgba(15, 23, 42, 0.06);
}

.tr:last-child {
  border-bottom: none;
}

.sku {
  font-weight: 600;
}

.price,
.inventory {
  font-variant-numeric: tabular-nums;
}

.price {
  font-weight: 600;
}

.status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 600;
}

.statusIn {
  background: rgba(16, 185, 129, 0.16);
  color: #0f766e;
}

.statusLow {
  background: rgba(245, 158, 11, 0.2);
  color: #92400e;
}

.statusOut {
  background: rgba(239, 68, 68, 0.18);
  color: #991b1b;
}

.notice {
  background: var(--surface-muted);
  border: 1px dashed rgba(15, 118, 110, 0.35);
  border-radius: 16px;
  padding: 16px 18px;
  color: var(--muted);
  font-size: 0.95rem;
}

.notice strong {
  color: var(--text);
}

@media (max-width: 720px) {
  .page {
    padding: 56px 20px 80px;
  }

  .header {
    align-items: flex-start;
  }

  .syncForm {
    width: 100%;
  }
}
EOF"
